@spec tv_fx_patch_spec  src=tests/specs/tv_fx_patch_spec.lua  loc=189  cases=14
@exercises dataStore (h.ds), trackerManager (h.tm), configManager (h.cm), trackerView (h.vm)
@surface   ds:assign, tm:rebuild, cm:getAt, vm:saveFxPatch, vm:setFxField, tm:subscribe, vm:loadFxPatch, vm:noteFx, vm:deleteFxPatch
@harness   mk

# Intent
  Pin-tests for the fx patch catalogue: `tv:saveFxPatch` stamps the caret host's
  chain into the tier it was handed -- verbatim, by copy, and without costing a
  re-derivation; `tv:loadFxPatch` copies a named chain back out onto a host,
  replacing what it held. Both name their tier rather than resolving one, a patch
  being held by copy. see design/note-macros-v2.md § The chain surface

# Helpers
  @fn injectRegion(h, fx)  @ 14-17
  @fn projectPatches(h)  @ 19
  @fn libraryPatches(h)  @ 20
  @fn withCatalogue(harness, project, library)  @ 27-32
      -- A region carrying `chain`, with the catalogue's two tiers seeded around it.

# Cases
  @case 'save stamps the host chain into the tier it was given, verbatim'  [harness]  @ 36-43
  @case 'save into the library tier writes the library tier, no project copy in the way'  [harness]  @ 47-54
  @case 'the catalogue holds a copy, not a live handle on the chain'  [harness]  @ 58-65
  @case 'saving re-realises nothing'  [harness]  @ 69-77
  @case 'a host with no chain saves nothing'  [harness]  @ 81-87
  @case 'the load replaces the host chain rather than appending to it'  [harness]  @ 93-98
  @case 'the host holds a copy, not a live handle on the catalogue'  [harness]  @ 102-108
  @case 'bypass rides the patch onto the host'  [harness]  @ 112-118
  @case 'each tier\'s copy of a name loads on its own, neither shadowing the other'  [harness]  @ 122-129
  @case 'a name the named tier does not hold loads nothing'  [harness]  @ 133-140
  @case 'deleting a project row leaves the library copy that shared the name standing'  [harness]  @ 146-152
  @case 'deleting a library row takes that copy and no other'  [harness]  @ 156-162
  @case 'the catalogue verbs re-realise nothing'  [harness]  @ 166-175
  @case 'the whole list lands in one write'  [harness]  @ 179-187

